const CUSTOMER_DISPATCH=Object.freeze({baseId:'appzJiskpAdaR1HEv',tableId:'tbljeIUoD7wwKuSmS',database:'lszh-offers',project:'lszh-automations',origin:'https://portal.lszh-automations.ch',archiveFolder:'10VD4xYIxfQBJ9Q5wpGq3iflK4MNJ1PHN',termsVersion:'1.0',termsId:'1d-EEo4AjsZBWvlYPlZLxxXuXJDBz7hWX',termsHash:'b5421778dd88bdac6697cb4f258319fba6577a9b26cba75509ef4e55df4fc2aa',avvMasterId:'1MhQvRxB_OsiBhLXSkGeVL-jGutO3vM8x'});
const SOURCE_KEYS=['Offerte','Offertennummer','Lead','Lead E-Mail','Lead Firma','Lead Name','Lead Strasse','Lead PLZ','Lead Ort','Lead Land','Leistung','Ausgangssituation','Ziel','Leistungsumfang','Nicht enthalten','Beteiligte Systeme','Einmalig CHF','Monatlich CHF','Zahlungsmodell','Zahlungsziel Tage','Gültig bis','Projektbedingungen Version','AVV erforderlich','Online-Annahme AVV Drive ID','Online-Annahme AVV-SHA256','Online-Annahme AVV-Version','Online-Annahme rechtlich freigegeben','Echtbetrieb – kein Test'];
