const sha=x=>createHash('sha256').update(x).digest('hex');
function reject(code){throw Error('customer_dispatch_'+code);}
function canonical(x){return Array.isArray(x)?x.map(canonical):x&&typeof x==='object'?Object.fromEntries(Object.keys(x).sort().map(k=>[k,canonical(x[k])])):x;}
function sourceFingerprint(f){return sha(JSON.stringify(canonical(SOURCE_KEYS.map(k=>[k,['Einmalig CHF','Monatlich CHF'].includes(k)?f[k]||0:f[k]??null]))));}
function offerFingerprint(s){return sha(JSON.stringify(canonical([s.tokenHash,s.status,s.approved,s.revision,s.termsVersion,s.expiresAt,s.recipientEmail,s.offerNumber,s.bundle,s.details,s.source,s.downstream])));}
function lookup(f,key){const a=f[key];if(!Array.isArray(a)||a.length!==1||typeof a[0]!=='string'||!a[0].trim()||a[0].length>200||/[\r\n]/.test(a[0]))reject('contact_'+key.replace(/[^A-Za-z]/g,''));return a[0].trim();}
function swissExpiry(day){
 if(typeof day!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(day)||!Number.isFinite(Date.parse(day))||new Date(day).toISOString().slice(0,10)!==day)reject('date');
 const label=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Zurich',timeZoneName:'shortOffset'}).formatToParts(new Date(day+'T12:00:00Z')).find(p=>p.type==='timeZoneName')?.value,m=/^GMT\+(\d{1,2})$/.exec(label||'');if(!m)reject('timezone');return new Date(day+'T23:59:59+'+m[1].padStart(2,'0')+':00').toISOString();
}
function money(v){const n=v??0;if(typeof n!=='number'||!Number.isFinite(n)||n<0||n>1000000||Math.abs(n*100-Math.round(n*100))>1e-7)reject('price');return n;}
function validateCustomerFields(row,now=new Date()){
 const f=row?.fields,I=CUSTOMER_DISPATCH;
 if(!REC.test(row?.id||'')||!f||Array.isArray(f))reject('record');
 if(f['Echtbetrieb – kein Test']!==true||f['Online-Annahme rechtlich freigegeben']!==true)reject('release');
 if(typeof f.Offertennummer!=='string'||f.Offertennummer.length<4||f.Offertennummer.length>100||/[\r\n]/.test(f.Offertennummer)||/^(TEST[-_]|DEMO[-_])|NO[_-]CONTRACT/i.test(f.Offertennummer)||/TEST_ONLY|NO[_-]CONTRACT|TEST_CRM_|TEST_MANUELL_/i.test(String(f['Interne Notiz']||'')))reject('test_source');
 if(!Array.isArray(f.Lead)||f.Lead.length!==1||!REC.test(f.Lead[0]))reject('lead');
 const email=lookup(f,'Lead E-Mail'),company=lookup(f,'Lead Firma');
 if(!/^[a-z0-9.!#$%&'*+\/=?^_`{|}~-]+@[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?\.[a-z]{2,63}$/.test(email)||/[\s,;<>]/.test(email)||/(?:^|\.)(?:example|invalid|test|localhost)(?:\.|$)/i.test(email.split('@')[1])||/^example\.(?:com|org|net)$/i.test(email.split('@')[1]))reject('recipient');
 if(/TEST_ONLY|NO[_-]CONTRACT|TEST_CRM_|TEST_MANUELL_/i.test(company))reject('test_company');
 for(const k of ['Lead Name','Lead Strasse','Lead PLZ','Lead Ort','Lead Land'])lookup(f,k);
 for(const k of ['Offerte','Leistung','Ausgangssituation','Ziel','Leistungsumfang','Nicht enthalten','Beteiligte Systeme','Zahlungsmodell'])if(typeof f[k]!=='string'||!f[k].trim()||f[k].length>12000)reject('required_'+k.replace(/[^A-Za-z]/g,''));
 if(!Number.isInteger(f['Zahlungsziel Tage'])||f['Zahlungsziel Tage']<1||f['Zahlungsziel Tage']>365)reject('payment_days');
 const once=money(f['Einmalig CHF']),monthly=money(f['Monatlich CHF']);if(once+monthly<=0)reject('price');
 if(f['Projektbedingungen Version']!==I.termsVersion||(f['Online-Annahme Bedingungen Drive ID']&&f['Online-Annahme Bedingungen Drive ID']!==I.termsId)||(f['Online-Annahme Bedingungen-SHA256']&&f['Online-Annahme Bedingungen-SHA256']!==I.termsHash))reject('terms');
 const expiresAt=swissExpiry(f['Gültig bis']);if(!(now instanceof Date)||!Number.isFinite(+now)||Date.parse(expiresAt)<=+now)reject('expired');
 const avv=f['AVV erforderlich'];if(!['Ja','Nein'].includes(avv))reject('avv_decision');
 if(avv==='Ja'){if(!FILE.test(f['Online-Annahme AVV Drive ID']||'')||[I.avvMasterId,I.termsId].includes(f['Online-Annahme AVV Drive ID'])||!SHA.test(f['Online-Annahme AVV-SHA256']||'')||typeof f['Online-Annahme AVV-Version']!=='string'||f['Online-Annahme AVV-Version'].length<4||f['Online-Annahme AVV-Version'].length>80||/test|draft|entwurf|rc|rahmenvorlage/i.test(f['Online-Annahme AVV-Version']))reject('avv_not_final');}
 else if(['Online-Annahme AVV Drive ID','Online-Annahme AVV-SHA256','Online-Annahme AVV-Version'].some(k=>f[k])||f['Online-Annahme AVV ausdrücklich akzeptiert'])reject('unexpected_avv');
 return{f,email,company,expiresAt,once,monthly};
}
function assertDraft(row,now){const v=validateCustomerFields(row,now),f=v.f;if(f.Status!=='Entwurf'||f.Schnellaktion!=='Für Versand freigeben'||f.Versandprüfung!=='BEREIT'||f['Vertragsunterlagen versendet']||f['Vertragsunterlagen akzeptiert']||f['Online-Annahme Zeitstempel']||f['Online-Annahme Link gesendet am']||f['Online-Annahme Token-Hash'])reject('not_draft');return v;}
