function preflight(row,now=new Date()){
 const f=row?.fields;if(!f||!REC.test(row?.id||''))return{ok:false,shouldWrite:false};
 if(f.Status!=='Entwurf'||f.Schnellaktion!=='Für Versand freigeben'||f['Online-Annahme Offerten Drive ID']||f['Online-Annahme Link gesendet am']||f['Online-Annahme Token-Hash']||['PDF angefordert','Mail reserviert','Manuelle Prüfung','Versandt'].includes(f.Versandstatus))return{ok:false,shouldWrite:false};
 try{const v=assertDraft(row,now);return{ok:true,shouldWrite:true,sourceFingerprint:sourceFingerprint(f),html:offerHtml(v),patchBody:JSON.stringify({fields:{Versandstatus:'PDF angefordert',Versandfehler:'','Versand freigegeben':true}})};}
 catch(e){const reason=/^customer_dispatch_[A-Za-z_]+$/.test(e.message)?e.message:'customer_dispatch_validation';return{ok:false,shouldWrite:true,patchBody:JSON.stringify({fields:{Versandstatus:'Blockiert',Versandfehler:f.Versandprüfung!=='BEREIT'?String(f.Versandprüfung||'Pflichtfelder prüfen'):reason,'Versand freigegeben':false,Schnellaktion:null}})};}
}
function verifyPdf(meta,base64,expected){const bytes=Buffer.from(base64||'','base64'),I=CUSTOMER_DISPATCH;if(!FILE.test(meta?.id||'')||meta.trashed===true||meta.mimeType!=='application/pdf'||meta.parents?.length!==1||meta.parents[0]!==I.archiveFolder||!meta.contentRestrictions?.some(x=>x.readOnly===true)||bytes.length<8||bytes.length>2*1024*1024||bytes.length!==Number(meta.size)||!bytes.subarray(0,5).equals(Buffer.from('%PDF-'))||!SHA.test(meta.sha256Checksum||'')||sha(bytes)!==meta.sha256Checksum||(expected&&(meta.id!==expected.id||meta.sha256Checksum!==expected.sha256)))reject('archive');return{id:meta.id,sha256:meta.sha256Checksum,base64:bytes.toString('base64')};}
function typed(v){if(v===null)return{nullValue:null};if(typeof v==='string')return{stringValue:v};if(typeof v==='boolean')return{booleanValue:v};if(typeof v==='number')return Number.isSafeInteger(v)?{integerValue:String(v)}:{doubleValue:v};if(Array.isArray(v))return{arrayValue:{values:v.map(typed)}};if(v&&typeof v==='object')return{mapValue:{fields:Object.fromEntries(Object.entries(v).map(([k,x])=>[k,typed(x)]))}};reject('firestore_type');}
function fields(v){return typed(v).mapValue.fields;}
function untyped(v){if('stringValue'in v)return v.stringValue;if('booleanValue'in v)return v.booleanValue;if('integerValue'in v)return Number(v.integerValue);if('doubleValue'in v)return v.doubleValue;if('nullValue'in v)return null;if(v.arrayValue)return(v.arrayValue.values||[]).map(untyped);if(v.mapValue)return Object.fromEntries(Object.entries(v.mapValue.fields||{}).map(([k,x])=>[k,untyped(x)]));reject('firestore_value');}
function root(){return'projects/'+CUSTOMER_DISPATCH.project+'/databases/'+CUSTOMER_DISPATCH.database+'/documents/';}
function preparedCommit(offer,fingerprint){const sent={...offer,status:'sent'},index={recordId:offer.source.recordId,tokenHash:offer.tokenHash,fingerprint:offerFingerprint(sent),schemaVersion:1};return{writes:[{update:{name:root()+'lszh_customer_source_index_v1/'+offer.source.recordId,fields:fields(index)},currentDocument:{exists:false}},{update:{name:root()+'lszh_customer_offers_v1/'+offer.tokenHash,fields:fields({...offer,dispatch:{state:'prepared',sourceFingerprint:fingerprint}})},currentDocument:{exists:false}}]};}
function mailMime(offer,code,documents){const I=CUSTOMER_DISPATCH,e=htmlEscape,link=I.origin+'/offerte-annehmen/#code='+code,boundary='lszh_'+offer.tokenHash,b64=x=>Buffer.from(x).toString('base64').match(/.{1,76}/g)?.join('\r\n')||'';const parts=['From: LSZH Automations <info@lszh-automations.ch>','To: '+offer.recipientEmail,'Subject: =?UTF-8?B?'+Buffer.from('Ihre Offerte '+offer.offerNumber+' – LSZH Automations').toString('base64')+'?=','Message-ID: <offer_'+offer.tokenHash+'@lszh-automations.ch>','MIME-Version: 1.0','Content-Type: multipart/mixed; boundary="'+boundary+'"','','--'+boundary,'Content-Type: text/html; charset=UTF-8','Content-Transfer-Encoding: base64','',b64('<p>Guten Tag</p><p>Im Anhang erhalten Sie unsere Offerte '+e(offer.offerNumber)+', die Projektbedingungen'+(offer.bundle.avv_required==='Ja'?' und Ihre kundenspezifische AVV':'')+'.</p><p><a href="'+e(link)+'">Offerte und Unterlagen prüfen</a></p><p>Die Offerte ist bis '+e(offer.expiresAt.slice(0,10))+' gültig. Der persönliche Link ist nur für Sie bestimmt.</p><p>Freundliche Grüsse<br>LSZH Automations · LSZH Invest GmbH</p>')];for(const kind of ['quote','terms',...(offer.bundle.avv_required==='Ja'?['avv']:[])])parts.push('--'+boundary,'Content-Type: application/pdf','Content-Disposition: attachment; filename="LSZH_'+{quote:'Offerte',terms:'Projektbedingungen',avv:'AVV'}[kind]+'.pdf"','Content-Transfer-Encoding: base64','',b64(Buffer.from(documents[kind].base64,'base64')));parts.push('--'+boundary+'--','');return JSON.stringify({raw:Buffer.from(parts.join('\r\n')).toString('base64url')});}
