function publicationCommit({row,prepared,receipt,storedOffer,storedIndex,offerUpdateTime,indexUpdateTime,now=new Date()}){
 const v=validateCustomerFields(row,now),f=v.f,o=prepared?.offer;if(!o||row.id!==o.source.recordId||sourceFingerprint(f)!==prepared.sourceFingerprint||f.Status!=='Versendet'||f['Vertragsunterlagen versendet']!==true||f['Versand freigegeben']!==true||f['Vertragsunterlagen akzeptiert']||f['Online-Annahme Zeitstempel']||f.Schnellaktion||f['Online-Annahme Token-Hash']!==o.tokenHash||f['Online-Annahme Link gesendet am']!==receipt?.sentAt||f['Online-Annahme Offerten Drive ID']!==o.bundle.quote.id||f['Online-Annahme Offerten-SHA256']!==o.bundle.quote.sha256||f['Online-Annahme Bedingungen Drive ID']!==o.bundle.terms.id||f['Online-Annahme Bedingungen-SHA256']!==o.bundle.terms.sha256||receipt.status!=='PROVIDER_CONFIRMED'||receipt.tokenHash!==o.tokenHash||receipt.recipientEmail!==o.recipientEmail||receipt.recordId!==row.id||!/^\d{4}-\d\d-\d\dT/.test(offerUpdateTime||'')||!/^\d{4}-\d\d-\d\dT/.test(indexUpdateTime||''))reject('publication_binding');
 const remote=untyped({mapValue:{fields:storedOffer?.fields||{}}}),index=untyped({mapValue:{fields:storedIndex?.fields||{}}});
 if(storedOffer?.updateTime!==offerUpdateTime||storedIndex?.updateTime!==indexUpdateTime||remote.status!=='prepared'||offerFingerprint(remote)!==offerFingerprint(o)||remote.dispatch?.state!=='prepared'||remote.dispatch.sourceFingerprint!==prepared.sourceFingerprint||index.recordId!==row.id||index.tokenHash!==o.tokenHash||index.fingerprint!==offerFingerprint({...o,status:'sent'}))reject('publication_conflict');
 const sent={...o,status:'sent',dispatch:{state:'provider_confirmed',sourceFingerprint:prepared.sourceFingerprint,gmailId:receipt.gmailId,sentAt:receipt.sentAt}};
 return{writes:[{update:{name:root()+'lszh_customer_offers_v1/'+o.tokenHash,fields:fields(sent)},currentDocument:{updateTime:offerUpdateTime}},{update:{name:root()+'lszh_customer_source_index_v1/'+row.id,fields:fields({recordId:row.id,tokenHash:o.tokenHash,fingerprint:offerFingerprint(sent),schemaVersion:1})},currentDocument:{updateTime:indexUpdateTime}}]};
}

return preflight(input.row);

