function mailMime(offer,code,documents){const I=CUSTOMER_DISPATCH,e=htmlEscape,link=I.origin+'/offerte-annehmen/#code='+code,boundary='lszh_'+offer.tokenHash,b64=x=>Buffer.from(x).toString('base64').match(/.{1,76}/g)?.join('\r\n')||'';const parts=['From: LSZH Automations <info@lszh-automations.ch>','To: '+offer.recipientEmail,'Subject: =?UTF-8?B?'+Buffer.from('Ihre Offerte '+offer.offerNumber+' – LSZH Automations').toString('base64')+'?=','Message-ID: <offer_'+offer.tokenHash+'@lszh-automations.ch>','MIME-Version: 1.0','Content-Type: multipart/mixed; boundary="'+boundary+'"','','--'+boundary,'Content-Type: text/html; charset=UTF-8','Content-Transfer-Encoding: base64','',b64('<p>Guten Tag</p><p>Im Anhang erhalten Sie unsere Offerte '+e(offer.offerNumber)+', die Projektbedingungen'+(offer.bundle.avv_required==='Ja'?' und Ihre kundenspezifische AVV':'')+'.</p><p><a href="'+e(link)+'">Offerte und Unterlagen prüfen</a></p><p>Die Offerte ist bis '+e(offer.expiresAt.slice(0,10))+' gültig. Der persönliche Link ist nur für Sie bestimmt.</p><p>Freundliche Grüsse<br>LSZH Automations · LSZH Invest GmbH</p>')];for(const kind of ['quote','terms',...(offer.bundle.avv_required==='Ja'?['avv']:[])])parts.push('--'+boundary,'Content-Type: application/pdf','Content-Disposition: attachment; filename="LSZH_'+{quote:'Offerte',terms:'Projektbedingungen',avv:'AVV'}[kind]+'.pdf"','Content-Transfer-Encoding: base64','',b64(Buffer.from(documents[kind].base64,'base64')));parts.push('--'+boundary+'--','');return JSON.stringify({raw:Buffer.from(parts.join('\r\n')).toString('base64url')});}
function prepareDispatch({row,expectedFingerprint,quoteMeta,quoteBase64,termsMeta,termsBase64,avvMeta,avvBase64,now=new Date()}){
 const v=assertDraft(row,now),f=v.f,I=CUSTOMER_DISPATCH;if(sourceFingerprint(f)!==expectedFingerprint)reject('source_changed');
 const quote=verifyPdf(quoteMeta,quoteBase64),terms=verifyPdf(termsMeta,termsBase64,{id:I.termsId,sha256:I.termsHash});if(f['Online-Annahme Offerten Drive ID']!==quote.id||f['Online-Annahme Offerten-SHA256']!==quote.sha256||f['Online-Annahme Offerten-Archivstatus']!=='VERIFIZIERT')reject('quote_binding');
 const avv=f['AVV erforderlich']==='Ja'?verifyPdf(avvMeta,avvBase64,{id:f['Online-Annahme AVV Drive ID'],sha256:f['Online-Annahme AVV-SHA256']}):null;if(new Set([quote.id,terms.id,...(avv?[avv.id]:[])]).size!==(avv?3:2))reject('duplicate_documents');
 const code=randomBytes(32).toString('base64url'),hash=sha(code),offer={tokenHash:hash,status:'prepared',approved:true,revision:1,termsVersion:I.termsVersion,expiresAt:v.expiresAt,recipientEmail:v.email,offerNumber:f.Offertennummer,details:{company:v.company,service:f.Leistung.slice(0,160),paymentModel:f.Zahlungsmodell.slice(0,160),onceCHF:v.once,monthlyCHF:v.monthly,...(avv?{avvVersion:f['Online-Annahme AVV-Version']}:{})},bundle:{avv_required:f['AVV erforderlich'],quote:{id:quote.id,sha256:quote.sha256},terms:{id:terms.id,sha256:terms.sha256},...(avv?{avv:{id:avv.id,sha256:avv.sha256}}:{})},source:{kind:'LSZH_CUSTOMER_APPROVED_V1',baseId:I.baseId,tableId:I.tableId,recordId:row.id,legalApproved:true,liveApproved:true},downstream:{airtable:'pending',proofPdf:'pending',email:'pending'}};
 return{sourceFingerprint:expectedFingerprint,tokenHash:hash,offer,preparedCommitBody:JSON.stringify(preparedCommit(offer,expectedFingerprint)),mailBody:mailMime(offer,code,{quote,terms,...(avv?{avv}:{})})};
}
function assertBeforeMail(row,prepared,now=new Date()){assertDraft(row,now);if(row.id!==prepared?.offer?.source?.recordId||sourceFingerprint(row.fields)!==prepared.sourceFingerprint)reject('source_changed_before_mail');return{ok:true};}
function confirmedMailReceipt(prepared,gmailId,now=new Date()){if(!/^[a-f0-9]{10,40}$/.test(gmailId||'')||!SHA.test(prepared?.tokenHash||'')||prepared.offer?.tokenHash!==prepared.tokenHash)reject('gmail_unconfirmed');return{status:'PROVIDER_CONFIRMED',gmailId,tokenHash:prepared.tokenHash,recordId:prepared.offer.source.recordId,recipientEmail:prepared.offer.recipientEmail,sourceFingerprint:prepared.sourceFingerprint,sentAt:now.toISOString()};}
function sentPatch(prepared,receipt){if(receipt?.status!=='PROVIDER_CONFIRMED'||receipt.tokenHash!==prepared.tokenHash||receipt.recordId!==prepared.offer.source.recordId||receipt.recipientEmail!==prepared.offer.recipientEmail)reject('receipt_binding');const I=CUSTOMER_DISPATCH;return{fields:{Status:'Versendet','Versendet am':new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Zurich'}).format(new Date(receipt.sentAt)),'Vertragsunterlagen versendet':true,'Online-Annahme Link gesendet am':receipt.sentAt,'Online-Annahme Token-Hash':prepared.tokenHash,'Online-Annahme Bedingungen Drive ID':I.termsId,'Online-Annahme Bedingungen-SHA256':I.termsHash,'Versand freigegeben':true,Schnellaktion:null,Versandstatus:'Mail bestätigt – Link wird veröffentlicht',Versandfehler:'','Nächster Schritt':'Mail bestätigt; Veröffentlichung des persönlichen Links ausstehend.'}};}
function publicationCommit({row,prepared,receipt,storedOffer,storedIndex,offerUpdateTime,indexUpdateTime,now=new Date()}){
 const v=validateCustomerFields(row,now),f=v.f,o=prepared?.offer;if(!o||row.id!==o.source.recordId||sourceFingerprint(f)!==prepared.sourceFingerprint||f.Status!=='Versendet'||f['Vertragsunterlagen versendet']!==true||f['Versand freigegeben']!==true||f['Vertragsunterlagen akzeptiert']||f['Online-Annahme Zeitstempel']||f.Schnellaktion||f['Online-Annahme Token-Hash']!==o.tokenHash||f['Online-Annahme Link gesendet am']!==receipt?.sentAt||f['Online-Annahme Offerten Drive ID']!==o.bundle.quote.id||f['Online-Annahme Offerten-SHA256']!==o.bundle.quote.sha256||f['Online-Annahme Bedingungen Drive ID']!==o.bundle.terms.id||f['Online-Annahme Bedingungen-SHA256']!==o.bundle.terms.sha256||receipt.status!=='PROVIDER_CONFIRMED'||receipt.tokenHash!==o.tokenHash||receipt.recipientEmail!==o.recipientEmail||receipt.recordId!==row.id||!/^\d{4}-\d\d-\d\dT/.test(offerUpdateTime||'')||!/^\d{4}-\d\d-\d\dT/.test(indexUpdateTime||''))reject('publication_binding');
 const remote=untyped({mapValue:{fields:storedOffer?.fields||{}}}),index=untyped({mapValue:{fields:storedIndex?.fields||{}}});
 if(storedOffer?.updateTime!==offerUpdateTime||storedIndex?.updateTime!==indexUpdateTime||remote.status!=='prepared'||offerFingerprint(remote)!==offerFingerprint(o)||remote.dispatch?.state!=='prepared'||remote.dispatch.sourceFingerprint!==prepared.sourceFingerprint||index.recordId!==row.id||index.tokenHash!==o.tokenHash||index.fingerprint!==offerFingerprint({...o,status:'sent'}))reject('publication_conflict');
 const sent={...o,status:'sent',dispatch:{state:'provider_confirmed',sourceFingerprint:prepared.sourceFingerprint,gmailId:receipt.gmailId,sentAt:receipt.sentAt}};
 return{writes:[{update:{name:root()+'lszh_customer_offers_v1/'+o.tokenHash,fields:fields(sent)},currentDocument:{updateTime:offerUpdateTime}},{update:{name:root()+'lszh_customer_source_index_v1/'+row.id,fields:fields({recordId:row.id,tokenHash:o.tokenHash,fingerprint:offerFingerprint(sent),schemaVersion:1})},currentDocument:{updateTime:indexUpdateTime}}]};
}

return{commitBody:JSON.stringify(publicationCommit(input))};
